'use strict';
const assert = require('node:assert/strict');
const P = require('./lib-load').loadP();
const C = P.CFG.levels;
const lower = C.istiklalRoute.tramY - C.tramRhythm.respiteBefore;
const upper = C.istiklalRoute.tramY + C.tramRhythm.encounterAfter;
const quiet = s => P.Levels.tramRespite(s);
const middle = (lower + upper) / 2;
const trial = P.createSim(42, { levelIndex: 3, tramRhythm: true });
P.startPlay(trial);
for (const [y, expect] of [[lower - 0.1, false], [lower, true], [middle, true], [upper, false]]) {
  trial.hero.y = y;
  assert.equal(quiet(trial), expect);
}
const control = P.createSim(42, { levelIndex: 3 });
control.hero.y = middle;
assert.equal(quiet(control), false);
assert.ok(!control.gen.marks.some(mark => mark.kind === 'tramEncounter'));

trial.hero.y = middle;
P.Levels.step(trial, 1 / P.CFG.sim.hz);
const spent = trial.gen.routeSpent;
P.Levels.step(trial, 2);
assert.equal(trial.gen.routeSpent, spent);
trial.hero.y = upper + 0.01;
P.Levels.step(trial, 1 / P.CFG.sim.hz);
const guard = trial.gen.tramGuard;
assert.ok(guard && guard.elite && guard.type === 'runner');
assert.ok(trial.ev.list.some(event => event.kind === 'ambush' && event.n === C.tramRhythm.ambushSize));
P.Levels.step(trial, 1 / P.CFG.sim.hz);
assert.strictEqual(trial.gen.tramGuard, guard);

const chests = trial.drops.filter(d => d.kind === 'chest').length;
P.Combat.damageEnemy(trial, guard, guard.hp * 2, 0, 1, 0, false, 'knife');
assert.equal(guard.dead, true);
assert.equal(trial.drops.filter(d => d.kind === 'chest').length, chests + 1);
console.log('tram rhythm: only the trial gets a quieter crossing, a one-time ambush and a chest-bearing runner');

for (let seed = 1; seed <= 50; seed++) {
  const s = P.createSim(seed, { levelIndex: 3, tramRhythm: true });
  assert.ok(s.geo.blocks.every(b => !P.Layouts.reserved(s.geo, b.x, b.y, b.w, b.h)), 'Switch and tracks stay clear in seed ' + seed);
}
for (const [mode, setup] of [['normal', 'lure'], ['normal', 'empty'], ['nightmare', 'hit']]) {
  const s = P.createSim(42, { levelIndex: 3, tramRhythm: true, loadout: { mode } });
  P.startPlay(s);
  const dt = 1 / P.CFG.sim.hz, tick = () => { s.t += dt; P.Hack.step(s, dt); };
  s.hero.y = upper + 0.01;
  P.Levels.step(s, dt);
  const H = s.gen.crossingControl, K = C.tramCrossing, p = P.Hack.crossingLane(H);
  assert.equal(H.state, 'idle');
  assert.equal(s.enemies.some(e => e.dead), false);
  s.enemies = [];
  Object.assign(s.hero, { x: H.x, y: H.y });
  for (let i = 0; H.state !== 'done' && i < 240; i++) tick();
  assert.ok(H.crossing, 'Player commits from the side of the tracks');
  assert.equal(H.crossing.warning, mode === 'nightmare' ? K.nightmareWarnT : K.warnT);
  assert.ok(!P.Hack.tramScene(s), 'Live encounter never freezes player input or the simulation');
  assert.equal(s.enemies.length, 0, 'Calling the live tram does not manufacture its own crowd');
  const on = setup === 'lure' ? P.Combat.spawnEnemy(s, 'walker', p.x, H.y, {}) : null;
  const off = P.Combat.spawnEnemy(s, 'walker', H.x, H.y + 2, {});
  if (setup === 'hit') s.hero.x = p.x;
  const hp = s.hero.hp;
  tick();
  assert.equal(s.hero.hp, hp, 'The warning plays before the hit');
  assert.ok(!on || !on.dead, 'No enemy takes damage during the warning');
  for (let i = 0; H.crossing && i < 480; i++) tick();
  assert.ok(!H.crossing && !off.dead);
  assert.ok(!on || on.dead);
  assert.equal(s.hero.hp < hp, setup === 'hit');
  const result = s.events.find(e => e.phase === 'tram_crossing_clear');
  assert.equal(result.kills, on ? 1 : 0);
  assert.equal(result.hitHero, setup === 'hit');
  assert.equal(s.events.filter(e => e.type === 'tramRush').length, 1);
  assert.ok(s.events.findIndex(e => e.type === 'tramWarning') < s.events.findIndex(e => e.type === 'tramRush'));
}

const stop = C.tramStop;
for (const seed of [26, 55]) {
  const layout = P.createSim(seed, { levelIndex: 2, tramRhythm: true });
  const points = [[stop.x, stop.y], [stop.x, stop.y + stop.chestAhead],
    [stop.trackX, stop.y + 8], [stop.trackX, stop.y + 10]];
  for (const [x, y] of points) {
    assert.ok(!layout.geo.blocks.some(b => Math.abs(b.x - x) < b.w / 2 + 0.4 && Math.abs(b.y - y) < b.h / 2 + 0.4),
      'stop, chest and track approach have clearance in seed ' + seed);
  }
}
const stopTrial = P.createSim(42, { levelIndex: 2, tramRhythm: true });
const stopControl = P.createSim(42, { levelIndex: 2 });
P.startPlay(stopTrial);
assert.equal(stopTrial.routeTrial, 'tram-stop');
assert.ok(!stopControl.gen.marks.some(mark => mark.kind === 'tramStop'));
assert.equal(stopTrial.geo.blocks.filter(b => b.kind === 'cm_tram_stop' && b.y === stop.y + stop.shelterAhead).length, 1);
P.Objectives.step(stopTrial, stopTrial.obj.T + 1);
assert.equal(stopTrial.obj.state, 'active', 'waiting at the start cannot complete the trial objective');
assert.equal(P.Objectives.status(stopTrial).line, 'obj.tramStop.approach');
stopTrial.hero.y = stop.y - stop.approach + 0.01;
P.Levels.step(stopTrial, 1 / P.CFG.sim.hz);
const terminal = stopTrial.gen.tramControl;
assert.equal(terminal.x, stop.x);
assert.equal(terminal.crowd, undefined, 'the scene crowd is absent during approach');
assert.equal(stopTrial.enemies.filter(e => e.type === 'crawler').length, 0, 'no scripted blockers in regular play');
P.Levels.step(stopTrial, 1 / P.CFG.sim.hz);
assert.strictEqual(stopTrial.gen.tramControl, terminal);
assert.equal(P.Objectives.status(stopTrial).line, 'obj.tramStop.link');
const beside = P.Combat.spawnEnemy(stopTrial, 'walker', stop.x, stop.y + 7);
const onTrack = P.Combat.spawnEnemy(stopTrial, 'walker', stop.trackX, stop.y + 8);
stopTrial.hero.x = stop.x;
stopTrial.hero.y = stop.y;
P.Hack.step(stopTrial, 0.25);
assert.equal(terminal.crowd, undefined, 'the scene crowd is absent while linking');
P.Hack.step(stopTrial, 24);
P.Objectives.step(stopTrial, 1 / P.CFG.sim.hz);
assert.equal(stopTrial.obj.state, 'active');
assert.equal(P.Objectives.status(stopTrial).line, 'obj.tramStop.incoming');
assert.equal(terminal.crowd.elapsed, 0, 'the crowd starts entering only after the link');
assert.ok(P.Hack.tramScene(stopTrial));
assert.equal(stopTrial.events.filter(e => e.type === 'tramRush').length, 0);
const clock = [stopTrial.t, stopTrial.runT], hp = stopTrial.hero.hp;
P.stepSim(stopTrial, stop.gatherT - stop.bellLead / 2, { x: -1, y: 1, dash: true });
assert.equal(stopTrial.events.filter(e => e.type === 'tramWarning').length, 1);
assert.equal(stopTrial.events.filter(e => e.type === 'tramRush').length, 0, 'the train waits for arrivals');
P.stepSim(stopTrial, stop.bellLead / 2 + stop.sweepT / 3, { x: -1, y: 1 });
assert.ok(!onTrack.dead, 'the tram still has to reach enemies down the rails');
P.stepSim(stopTrial, stop.sweepT * 2 / 3 + 0.01, {});
assert.ok(onTrack.dead && !stopTrial.milestone.open, 'the horde falls before the camera settles and the gate opens');
assert.deepEqual([stopTrial.hero.x, stopTrial.hero.y, stopTrial.hero.hp], [stop.x, stop.y, hp]);
assert.deepEqual([stopTrial.t, stopTrial.runT], clock, 'the cutscene freezes the run and its timers');
P.stepSim(stopTrial, stop.returnT, {});
assert.equal(stopTrial.obj.state, 'done');
assert.ok(!beside.dead, 'the control ring is beside the damage lane');
const rushes = stopTrial.events.filter(e => e.type === 'tramRush');
assert.equal(rushes.length, 1);
assert.equal(rushes[0].x, stop.trackX);
assert.ok(stopTrial.drops.some(d => d.kind === 'chest' && d.y === stop.y + stop.chestAhead));
assert.ok(stopTrial.milestone.open);
assert.ok(!P.Hack.tramScene(stopTrial));
P.stepSim(stopTrial, 1 / P.CFG.sim.hz, { x: -1, y: 0 });
assert.ok(stopTrial.hero.x < stop.x, 'motion resumes after the set piece');
const bypass = P.createSim(42, { levelIndex: 2, tramRhythm: true });
P.startPlay(bypass);
bypass.hero.y = bypass.geo.holdY;
P.World.clampHero(bypass, bypass.hero);
assert.ok(bypass.hero.y < bypass.milestone.y);
assert.ok(!bypass.gen.frenzy, 'the finale is beyond the blocked tracks');
bypass.milestone.open = true; // Exercise the finale independently of the tram test above.
bypass.hero.y = bypass.geo.holdY;
P.Levels.step(bypass, 0.1);
const wave = bypass.gen.frenzy, finale = C.tramFinale;
assert.equal(wave.phase, 'warning');
assert.ok(!bypass.gen.boss);
P.Levels.step(bypass, finale.warningT);
assert.equal(wave.phase, 'active');
assert.equal(wave.enemies.length, finale.packs[0].length);
P.Levels.step(bypass, finale.secondAt);
assert.equal(wave.enemies.length, finale.packs.flat().length);
assert.ok(wave.enemies.some(e => e.elite));
wave.enemies.slice(0, finale.chestKills).forEach(e => { e.dead = true; });
const frenzyChests = bypass.drops.filter(d => d.kind === 'chest').length;
bypass.horde = { queue: [{ due: 1, side: 1 }] };
bypass.enemyTele.push({ then: 'surge' });
P.Levels.step(bypass, finale.waveT);
assert.equal(wave.phase, 'done');
assert.equal(bypass.drops.filter(d => d.kind === 'chest').length, frenzyChests + 1);
assert.equal(bypass.horde.queue.length, 0);
assert.ok(!bypass.enemyTele.some(t => t.then === 'surge'));
const boss = bypass.gen.boss;
assert.ok(boss && boss.bossPreset === 'switchkeeper');
assert.equal(bypass.props.shutterOpen, false);
bypass.enemies = [boss];
boss.state = 'active';
boss.ai.cd = 0;
P.Bosses.think(bypass, boss, 0);
assert.equal(boss.ai.act, 'switchRails','The first lesson is the rail refuge');
const lanes = bypass.enemyTele.filter(t => t.then === 'switchRails');
assert.equal(lanes.length,1,'First rail cast leaves two refuge lanes');
const safe = [-1, 0, 1].map(i => i * P.CFG.bosses.switchkeeper.rails.spacing).find(x => lanes.every(lane => lane.x !== x));
bypass.hero.x = safe; bypass.hero.y = lanes[0].y + 1;
const healthy = bypass.hero.hp;
for (const lane of lanes) P.Bosses.hitRails(bypass, lane);
assert.equal(bypass.hero.hp, healthy);
bypass.hero.x = lanes[0].x;
P.Bosses.hitRails(bypass, lanes[0]);
assert.ok(bypass.hero.hp < healthy);
P.Bosses.think(bypass,boss,boss.ai.W);
boss.ai.m='walk';boss.ai.cd=0;boss.ai.needPause=false;
P.Bosses.think(bypass,boss,0);
assert.equal(boss.ai.act,'switchHook','The next response is the close hook');
P.Bosses.think(bypass,boss,boss.ai.W);
assert.ok(boss.exposed && boss.ai.m==='switchRecover','A spent hook leaves a real opening');
boss.hp=boss.maxHp*.40;boss.ai.m='walk';boss.ai.cd=0;
const phaseWarnings=new Set(bypass.enemyTele);
P.Bosses.think(bypass,boss,0);P.Bosses.think(bypass,boss,2);P.Bosses.think(bypass,boss,0);
assert.equal(boss.ai.act,'switchRails','After the hook, phase transition advances to the changed two-rail response');
assert.equal(bypass.enemyTele.filter(t=>!phaseWarnings.has(t)&&t.then==='switchRails').length,2,'Later rails change the actual refuge');
P.Bosses.think(bypass,boss,boss.ai.W);
boss.ai.m='walk';boss.ai.cd=0;boss.ai.needPause=false;
P.Bosses.think(bypass,boss,0);
assert.equal(boss.ai.act,'switchHook','The close response follows the new rail pattern without a repeated hook reset');
P.Combat.damageEnemy(bypass, boss, boss.hp * 4, 0, 1, 0, false, 'knife');
P.Levels.step(bypass, 0.1);
bypass.hero.y = bypass.geo.exitY + 1;
P.Levels.step(bypass, 1 / P.CFG.sim.hz);
P.Objectives.step(bypass, 1 / P.CFG.sim.hz);
assert.equal(bypass.mode, 'won');
assert.equal(bypass.obj.state, 'failed', 'the isolated finale test did not operate a tram');
console.log('tram stop: timed track contact, one chest, two finite frenzy packs and a two-phase final boss');

const dt = 1 / P.CFG.sim.hz;
const opening = P.createSim(42, { levelIndex: 1, tramRhythm: true });
P.startPlay(opening);
opening.hero.y = P.CFG.level.holdTriggerY;
P.Director.step(opening, C.istiklalFinales[1].holdBefore - dt);
assert.ok(!opening.dir.trialBoss, 'the shutter defense happens before the Cook arrives');
P.Director.step(opening, 2 * dt);
assert.equal(opening.dir.trialBoss.bossPreset, 'cook');
assert.ok(!opening.props.shutterOpen);
P.Combat.damageEnemy(opening, opening.dir.trialBoss, opening.dir.trialBoss.hp * 4, 0, 1, 0, false, 'knife');
P.Director.step(opening, dt);
assert.ok(opening.props.shutterOpen);

const [market, wires, depot] = [3, 4, 5].map(index => P.createSim(42, { levelIndex: index, tramRhythm: true }));
const gates = P.CFG.levels.routeMilestones;
P.startPlay(wires);
const wire = wires.obj.items[0];
const target = P.Combat.spawnEnemy(wires, 'walker', wire.x + 0.5, wire.y, { state: 'active' });
Object.assign(wires.hero, { x: wire.x, y: wire.y });
P.Objectives.step(wires, dt);
assert.equal(wires.obj.prog, 0, 'touching the wire does not cut it instantly');
wires.hero.y += 3;
P.Objectives.step(wires, dt);
assert.equal(wire.progress, 0, 'stepping out of the ring releases the tool');
wires.hero.y = wire.y;
P.Objectives.step(wires, gates.wires.cutT);
P.Objectives.step(wires, dt);
assert.equal(wires.obj.prog, 1);
assert.equal(wires.events.filter(e => e.type === 'wirePulse').length, 1);
assert.ok(target.hp < target.maxHp, 'the cable pulse hits a nearby enemy');

for (const it of wires.obj.items.slice(1)) {
  Object.assign(wires.hero, { x: it.x, y: it.y });
  P.Objectives.step(wires, gates.wires.cutT);
}
assert.equal(wires.obj.prog, 3);
assert.ok(!wires.milestone.open, 'the cable barrier has a visible opening phase');
P.RouteMilestones.step(wires, gates.openT);
assert.ok(wires.milestone.open);

const cart = market.obj.b;
assert.ok(cart.y > C.istiklalRoute.tramY);
Object.assign(market.hero, { x: cart.x, y: cart.y });
const jam = P.Combat.spawnEnemy(market, 'walker', cart.x, cart.y, { state: 'active' });
P.Objectives.step(market, cart.uploadT);
assert.ok(cart.contested && cart.up === 0);
jam.dead = true;
P.Objectives.step(market, cart.uploadT);
P.RouteMilestones.step(market, gates.openT);
assert.ok(market.milestone.open);

depot.hero.y = depot.geo.holdY;
P.Levels.step(depot, dt);
assert.ok(!depot.gen.boss, 'the depot is closed before the crank is turned');
const crank = depot.milestone.point;
Object.assign(depot.hero, { x: crank.x, y: crank.y });
P.RouteMilestones.step(depot, gates.depot.crankT);
assert.equal(crank.progress, 1);
P.RouteMilestones.step(depot, gates.openT);
assert.ok(depot.milestone.open);

for (const [s, preset, first] of [[market, 'roaster', 'charge'], [wires, 'linekeeper', 'arcRelay'], [depot, 'vatman', 'districtTram']]) {
  P.startPlay(s);
  s.hero.y = s.geo.holdY;
  P.Levels.step(s, dt);
  const boss = s.gen.boss;
  assert.equal(boss.bossPreset, preset);
  assert.ok(!s.props.shutterOpen);
  boss.state = 'active'; boss.ai.cd = 0;
  if(preset==='linekeeper'){
    P.Bosses.think(s,boss,dt);
    assert.equal(boss.ai.act,null,'The cable worker first closes the actual engagement distance');
    assert.ok(Math.hypot(boss.dvx,boss.dvy)>0,'A distant relay cannot remain a stationary remote-cast loop');
    s.hero.x=boss.x;s.hero.y=boss.y-P.CFG.bosses.linekeeper.attackApproach+.1;
  }
  P.Bosses.think(s, boss, dt);
  assert.equal(boss.ai.act, first);
  if (preset !== 'vatman') continue;
  const lane = s.enemyTele.find(t => t.then === 'districtTram');
  s.hero.y = lane.y + lane.len * 0.75;
  s.hero.x = lane.x;
  const hp = s.hero.hp;
  P.Enemies.onTele(s, lane);
  P.IstiklalTrial.step(s, 0.2);
  assert.equal(s.hero.hp, hp, 'the boss tram takes time to reach the hero');
  s.hero.x = lane.x + lane.w;
  const caught = P.Combat.spawnEnemy(s, 'walker', lane.x, s.hero.y, { state: 'active' });
  const caughtHp = caught.hp;
  P.IstiklalTrial.step(s, P.CFG.bosses.vatman.tram.sweep);
  assert.equal(s.hero.hp, hp, 'stepping off the tracks avoids the tram');
  assert(caught.hp < caughtHp && boss.exposed, 'the tram clears its lane and opens the Vatman to a counter');
  P.Combat.damageEnemy(s, boss, boss.maxHp * 0.5, 0, 1, 0, false, 'knife');
  boss.ai.m = 'walk'; boss.ai.cd = 0;
  P.Bosses.think(s, boss, dt);
  assert.equal(boss.phase, 2);
  P.Bosses.think(s, boss, P.CFG.bosses.vatman.pause + dt);
  P.Bosses.think(s, boss, dt);
  assert.equal(boss.ai.act, 'vatmanLever');
}
console.log('İstiklal finales: shutter defense, five distinct bosses, working wires and a moving tram lane');

const street = P.createSim(42, { levelIndex: 2 });
const portal = street.env.portals[0], window = P.CFG.env.portal;
street.env.portals = [portal];
street.env.rng.chance = () => true;
street.hero.y = portal.y;
P.EnvPortal.step(street, 1);
assert.equal(portal.state, 'open');
P.EnvPortal.step(street, 2);
P.EnvPortal.step(street, 2);
assert.ok(portal.passed && portal.state === 'idle');
const openings = street.env.stats.portals;
street.hero.y = portal.y - window.behind - 1;
P.EnvPortal.step(street, 1);
street.hero.y = portal.y;
P.EnvPortal.step(street, 1);
assert.equal(street.env.stats.portals, openings, 'walking back and forth cannot reset an opening in early Normal');
